CODIGOS = ["en", "es", "de", "fr", "it", "pl", "ja", "zh-CN",
           "ar", "ko", "bn"]


def normalizar(texto):
    return u" ".join((texto or u"").split())


def construir():
    fora = {c: {} for c in CODIGOS}
    for linha in TABELA:
        pt = normalizar(linha[0])
        if not pt:
            continue
        for i, cod in enumerate(CODIGOS, start=1):
            alvo = normalizar(linha[i]) if i < len(linha) else u""
            if alvo and alvo != pt:
                fora[cod][pt] = alvo
    return fora


def cobertura():
    d = construir()
    total = len({normalizar(l[0]) for l in TABELA if normalizar(l[0])})
    return {"frases": total,
            "por_idioma": {c: len(d[c]) for c in CODIGOS}}
